// KDA chain spec-verify on gfx950 with sglang's ReplaySSM ring (Kimi-K3's linear attention), one launch
// for a batch of requests of kT verify tokens each. Per request and head: the width-4 causal conv1d of
// the slot's three-token history and the tokens' packed q | k | v channels, SiLU and the bf16 round trip
// of its outputs; q and k l2-normalized, q times scale; the gate g = lower_bound * sigmoid(exp(A_log) *
// (a + dt_bias)), or the softplus gate, and beta = sigmoid(b); the ring rows (raw v, raw k, g, beta) and
// the conv windows; then each token's output of the gated delta rule from the slot's state h0, read only,
// without a serial recurrence. With D_t the running product of the decays exp(g), a_t = (D_t k_t) . h0
// and b_t = (D_t q_t) . h0 per value column, and A_ts (s < t) / B_ts (s <= t) the sums over K rows of
// k_t k_s / q_t k_s times the decays of tokens s + 1 .. t: vn_t = (v_t - a_t - sum_{s<t} A_ts vn_s) *
// beta_t (a kT x kT lower-triangular solve) and o_t = b_t + sum_{s<=t} B_ts vn_s. A padding request
// (cache index < 0) writes zero output and nothing else.
//
// Block = 4 waves on one (request, head) and 32 * kC value columns, 4 / kC consecutive blocks a head.
// Phase 1 computes everything that does not depend on the state for all kT tokens at once (conv outputs,
// q / k norms, gate decays, beta) into LDS and writes the ring and conv-window rows; phase 1b the decayed
// q / k and the A / B entries (16-lane partial sums); phase 2 the h0 products of each lane's kC value
// columns (lane (cg = lane / 8, j = lane % 8) holds K rows {32 m + 4 j + e}) and the solve, lane j
// storing token j.
//
// source: Kimi-K3.1-Pro kernel drop (Hyperloom), code/sglang/3-C_kda.diff
// file: python/sglang/kernels/jit/csrc/attention/hl_kda_verify_gfx950.cuh, instantiated with kFB = kON = false
// variant of: sglang's python/sglang/kernels/jit/csrc/attention/kda_verify_gfx950.cuh (sglang 0.5.24.dev809, Apache-2.0)

#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>

#include <cstdint>
#include <optional>

namespace {

constexpr int kKdaK = 128;
constexpr int kKdaV = 128;
constexpr int kWave = 64;

struct HlKdaVerifyParams {
  const uint16_t* __restrict__ x;              // [seq_len, dim] bf16, pre-conv q | k | v
  const float* __restrict__ conv_w;            // [dim, 4]
  const uint16_t* __restrict__ conv_state;     // [slots, 3, dim] bf16, dim contiguous
  const int32_t* __restrict__ cache_indices;   // [B] conv / ssm / ring slot, < 0 = padded row
  uint16_t* __restrict__ window;               // [lines, steps, 3, dim] bf16, dim contiguous
  const int32_t* __restrict__ window_indices;  // [B]
  const uint16_t* __restrict__ a;              // [seq_len, HV * K] bf16
  const uint16_t* __restrict__ b;              // [seq_len, HV] bf16
  const float* __restrict__ A_log;             // [HV]
  const float* __restrict__ dt_bias;           // [HV * K]
  const float* __restrict__ state;             // [slots, HV, V, K]
  uint16_t* __restrict__ rawv;                 // [slots, HV, L, V] bf16
  uint16_t* __restrict__ rawk;                 // [slots, H, L, K] bf16
  float* __restrict__ ring_g;                  // [slots, HV, L, K]
  float* __restrict__ ring_beta;               // [slots, HV, L]
  uint16_t* __restrict__ o;                    // [seq_len, HV, V] bf16
  int64_t stride_x_tok;
  int64_t stride_cs_line;
  int64_t stride_cs_win;
  int64_t stride_iw_line;
  int64_t stride_iw_step;
  int64_t stride_iw_win;
  int64_t stride_a_tok;
  int64_t stride_b_tok;
  int64_t stride_state_slot;
  int64_t stride_rawv_slot;
  int64_t stride_rawk_slot;
  int64_t stride_g_slot;
  int64_t stride_beta_slot;
  float scale;
  float lower_bound;
  float softplus_beta;
  float softplus_threshold;
  int32_t num_heads;
  int32_t ring_len;
};

__device__ __forceinline__ float bf16_to_f32(uint16_t v) {
  return __uint_as_float(static_cast<uint32_t>(v) << 16);
}

// Round to nearest even, as torch / Triton fp32 -> bf16 (inputs are finite).
__device__ __forceinline__ uint16_t f32_to_bf16(float f) {
  uint32_t u = __float_as_uint(f);
  u += 0x7fffu + ((u >> 16) & 1u);
  return static_cast<uint16_t>(u >> 16);
}

template <int kCtrl>
__device__ __forceinline__ float dpp_add(float x) {
  const int moved = __builtin_amdgcn_update_dpp(0, __float_as_int(x), kCtrl, 0xf, 0xf, false);
  return x + __int_as_float(moved);
}

// Butterfly sum over aligned groups of kLanes (4, 8 or 16) lanes inside a DPP row; every lane of
// the group ends with the group total.
template <int kLanes>
__device__ __forceinline__ float group_sum(float x) {
  x = dpp_add<0xb1>(x);                               // quad_perm [1, 0, 3, 2]
  x = dpp_add<0x4e>(x);                               // quad_perm [2, 3, 0, 1]
  if constexpr (kLanes >= 8) x = dpp_add<0x141>(x);   // row_half_mirror
  if constexpr (kLanes >= 16) x = dpp_add<0x140>(x);  // row_mirror
  return x;
}

__device__ __forceinline__ float sigmoid(float x) {
  return 1.0f / (1.0f + __expf(-x));
}

// c0 * w0 + c1 * w1 + c2 * w2 + x * w3 in float32, then SiLU (the bf16 round trip of its output is the
// caller's).
__device__ __forceinline__ float conv_silu(float c0, float c1, float c2, float xt, const float (&w)[4]) {
  const float acc = c0 * w[0] + c1 * w[1] + c2 * w[2] + xt * w[3];
  return acc / (1.0f + __expf(-acc));
}

template <bool kLowerBound>
__device__ __forceinline__ float kda_gate(float a, float dt_bias, float exp_a_log, const HlKdaVerifyParams& p) {
  const float x = a + dt_bias;
  if constexpr (kLowerBound) {
    return p.lower_bound * sigmoid(exp_a_log * x);
  } else {
    const float bx = p.softplus_beta * x;
    const float sp = bx <= p.softplus_threshold ? (1.0f / p.softplus_beta) * __logf(1.0f + __expf(bx)) : x;
    return -exp_a_log * sp;
  }
}

// The gate where exp(A_log) passes float32 (a head-uniform, rare path): its products with exp(A_log) from logs,
// so a zero factor gives 0 rather than inf * 0.
template <bool kLowerBound>
__device__ __forceinline__ float kda_gate_wide(float a, float dt_bias, float a_log, const HlKdaVerifyParams& p) {
  const float x = a + dt_bias;
  if constexpr (kLowerBound) {
    return p.lower_bound * sigmoid(x == 0.0f ? 0.0f : copysignf(expf(a_log + logf(fabsf(x))), x));
  } else {
    const float bx = p.softplus_beta * x;
    // log(softplus): bx - log(beta) where exp(bx) is below float32's epsilon, as log1p(e) = e there
    const float lsp = bx < -20.0f ? bx - logf(p.softplus_beta)
                      : logf(bx <= p.softplus_threshold ? log1pf(expf(bx)) / p.softplus_beta : x);
    return -expf(a_log + lsp);
  }
}

__device__ __forceinline__ float bf16_lane(const uint4& v, int i) {
  const uint32_t w = (&v.x)[i >> 1];
  return __uint_as_float((i & 1) ? (w & 0xffff0000u) : (w << 16));
}

__device__ __forceinline__ uint4 pack_bf16x8(const float (&f)[8]) {
  uint4 r;
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    (&r.x)[i] = static_cast<uint32_t>(f32_to_bf16(f[2 * i])) | (static_cast<uint32_t>(f32_to_bf16(f[2 * i + 1])) << 16);
  }
  return r;
}

template <typename T>
__device__ __forceinline__ T load_as(const void* ptr) {
  return *reinterpret_cast<const T*>(ptr);
}

template <typename T>
__device__ __forceinline__ void store_as(void* ptr, const T& value) {
  *reinterpret_cast<T*>(ptr) = value;
}

// Raw bf16 input of channel `ch` at position `pos` of the conv sequence [cs0, cs1, cs2, x0, x1, ...]:
// the conv state for pos < 3, else token pos - 3.
__device__ __forceinline__ const uint16_t* seq_ptr(const HlKdaVerifyParams& p, const uint16_t* cs, int64_t bos, int pos, int64_t ch) {
  return pos < 3 ? cs + ch + pos * p.stride_cs_win : p.x + (bos + pos - 3) * p.stride_x_tok + ch;
}

// Conv + SiLU + bf16 round trip over 8 channels for one token: hist = sequence positions t .. t + 3.
__device__ __forceinline__ void conv_octet(const uint4 (&hist)[4], const float4 (&w)[8], float (&y)[8]) {
#pragma unroll
  for (int i = 0; i < 8; ++i) {
    const float wi[4] = {w[i].x, w[i].y, w[i].z, w[i].w};
    y[i] = bf16_to_f32(f32_to_bf16(
        conv_silu(bf16_lane(hist[0], i), bf16_lane(hist[1], i), bf16_lane(hist[2], i), bf16_lane(hist[3], i), wi)));
  }
}

// Block = 4 waves sharing one head's state-independent work (phase 1) for 4 * BV value columns;
// each wave then takes its own [K, BV] slice of h0 (phase 2).
template <int kC, int kT, bool kLowerBound>
__global__ __launch_bounds__(256) void hl_kda_verify_kernel(const HlKdaVerifyParams p) {
  constexpr int K = kKdaK;
  constexpr int V = kKdaV;
  constexpr int kWaves = 4;
  constexpr int kBlock = kWave * kWaves;
  // phase 2: lane (cg = lane / 8, j = lane % 8) holds kC value columns x K rows {32 m + 4 j + e};
  // the K reductions stay inside the 8-lane group, and each LDS vector read feeds kC columns.
  constexpr int kBV = 8 * kC;          // value columns per wave
  constexpr int kCols = kWaves * kBV;  // value columns per block
  constexpr int kBlocksPerHead = V / kCols;
  constexpr int kVIters = (kCols * kT + kBlock - 1) / kBlock;
  // The gate and the q / k conv map the block onto 8 token groups; groups past kT idle.
  constexpr int kTokenGroups = 8;
  constexpr int kGateLanes = kBlock / kTokenGroups;  // lanes per token for the gate, kGateRows rows each
  constexpr int kGateRows = K / kGateLanes;
  static_assert(kC == 1 || kC == 2 || kC == 4, "1, 2 or 4 columns per lane");
  static_assert(kT >= 1 && kT <= kTokenGroups, "T must be 1..8");
  static_assert(kGateRows * kGateLanes == K && kGateRows % 2 == 0, "unsupported gate mapping");

  __shared__ float s_q[kT][K];
  __shared__ float s_k[kT][K];
  __shared__ float s_decay[kT][K];
  __shared__ float s_v[kT][kCols];
  __shared__ float s_beta[kT];
  __shared__ float s_kd[kT][K];  // D_t * k_t
  __shared__ float s_qd[kT][K];  // D_t * q_t
  constexpr int kNA = kT * (kT - 1) / 2, kNB = kT * (kT + 1) / 2, kNAB = kNA + kNB;
  __shared__ float s_part[8][kNAB];  // per 16-lane row partial sums of A, B (waves 0-1)
  __shared__ float s_ab[kNAB];

  const int tid = threadIdx.x;
  const int wave = tid / kWave;
  const int lane = tid % kWave;
  // one-dimensional grid in the order of a (kBlocksPerHead, B * H) grid
  const int i_v = static_cast<int>(blockIdx.x % kBlocksPerHead);
  const int byy = static_cast<int>(blockIdx.x / kBlocksPerHead);
  const int H = p.num_heads;
  const int i_n = byy / H;
  const int hv = byy % H;
  const int slot = p.cache_indices[i_n];
  const int64_t slot_ld = slot < 0 ? 0 : slot;  // padded row: load from slot 0, store no state
  const int j = lane & 7;
  const int cg = lane >> 3;
  const int col0 = i_v * kCols + wave * kBV + cg * kC;
  const int64_t bos = static_cast<int64_t>(i_n) * kT;
  const bool owner = i_v == 0;
  const int widx = p.window_indices[i_n];
  const uint16_t* cs = p.conv_state + slot_ld * p.stride_cs_line;

  // ---- global loads, all issued before the first global store (on CDNA vmcnt also counts
  // stores, so a load behind a store waits for its acknowledgement) ----
  // q / k conv: DPP row r (16 lanes x 8 channels = one head) takes token r % 8 of q (r < 8) or k.
  const int row = (tid >> 4) & 15;  // threads past 256 duplicate rows 0..15 and store nothing
  const int conv_t = min(row & 7, kT - 1);
  const bool conv_valid = (row & 7) < kT && tid < 256;
  const bool is_k = row >= 8;
  const int c8 = (tid & 15) * 8;
  const int64_t cch = (is_k ? static_cast<int64_t>(H) * K : 0) + static_cast<int64_t>(hv) * K + c8;
  uint4 hist[4];
  float4 w[8];
#pragma unroll
  for (int i = 0; i < 8; ++i)
    w[i] = load_as<float4>(p.conv_w + (cch + i) * 4);

  // gate: token tid / kGateLanes, K rows [g0, g0 + kGateRows)
  const int gate_t = min(tid / kGateLanes, kT - 1);
  const bool gate_valid = tid / kGateLanes < kT;
  const int g0 = (tid % kGateLanes) * kGateRows;
  uint32_t a_raw[kGateRows / 2];
  float dt[kGateRows];
#pragma unroll
  for (int i = 0; i < kGateRows; i += 2) {
    a_raw[i / 2] = load_as<uint32_t>(p.a + (bos + gate_t) * p.stride_a_tok + hv * K + g0 + i);
    const float2 d = load_as<float2>(p.dt_bias + hv * K + g0 + i);
    dt[i] = d.x;
    dt[i + 1] = d.y;
  }
  const float a_log = p.A_log[hv];
  const float b_raw = bf16_to_f32(p.b[(bos + min(tid, kT - 1)) * p.stride_b_tok + hv]);

  // v conv: one (column, token) per lane and iteration
  uint16_t v_hist[kVIters][4];
  float4 wv[kVIters];
#pragma unroll
  for (int it = 0; it < kVIters; ++it) {
    const int idx = min(tid + it * kBlock, kCols * kT - 1);
    const int64_t vc = 2LL * H * K + static_cast<int64_t>(hv) * V + i_v * kCols + idx % kCols;
#pragma unroll
    for (int i = 0; i < 4; ++i)
      v_hist[it][i] = *seq_ptr(p, cs, bos, idx / kCols + i, vc);
    wv[it] = load_as<float4>(p.conv_w + vc * 4);
  }
#pragma unroll
  for (int i = 0; i < 4; ++i)
    hist[i] = load_as<uint4>(seq_ptr(p, cs, bos, conv_t + i, cch));
  float h[kC][16];  // lane (cg = lane / 8, j = lane % 8): kC columns x rows {32 m + 4 j + e}
  {
    const float* hp = p.state + slot_ld * p.stride_state_slot + (static_cast<int64_t>(hv) * V + col0) * K + j * 4;
#pragma unroll
    for (int cc = 0; cc < kC; ++cc)
#pragma unroll
      for (int m = 0; m < 4; ++m) {
        const float4 x = load_as<float4>(hp + cc * K + 32 * m);
        h[cc][4 * m] = x.x; h[cc][4 * m + 1] = x.y; h[cc][4 * m + 2] = x.z; h[cc][4 * m + 3] = x.w;
      }
  }

  asm volatile("" ::: "memory");  // keep every load above ahead of the compute and stores below
  if (slot < 0) {  // padded graph row: zero output, no state or window written
    for (int idx = tid; idx < kCols * kT; idx += kBlock)
      p.o[((bos + idx / kCols) * H + hv) * V + i_v * kCols + idx % kCols] = 0;
    return;
  }

  // ---- phase 1: state-independent work for all T tokens ----
  float y[8];
  conv_octet(hist, w, y);
  float ss = 0.0f;
#pragma unroll
  for (int i = 0; i < 8; ++i)
    ss += y[i] * y[i];
  ss = group_sum<16>(ss);
  float rn;
  if (__builtin_isinf(ss)) {
    // the squares pass float32 (a rare path, uniform over the 16 lanes of the row): summed again scaled by 2^-100,
    // exactly; past 2^62 the norm leaves eps, and any square 2^-120 or more below the largest, beneath its ulp
    float s2 = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) {
      const float t = y[i] * 0x1p-100f;
      s2 += t * t;
    }
    rn = 0x1p-100f / sqrtf(group_sum<16>(s2));
  } else {
    rn = 1.0f / sqrtf(ss + 1e-6f);
  }
  rn *= is_k ? 1.0f : p.scale;
  if (conv_valid) {
    float* dst = is_k ? &s_k[conv_t][c8] : &s_q[conv_t][c8];
    store_as<float4>(dst, make_float4(y[0] * rn, y[1] * rn, y[2] * rn, y[3] * rn));
    store_as<float4>(dst + 4, make_float4(y[4] * rn, y[5] * rn, y[6] * rn, y[7] * rn));
  }
  const float exp_a_log = __expf(a_log);
  float g[kGateRows];
#pragma unroll
  for (int i = 0; i < kGateRows; ++i) {
    const uint32_t pair = a_raw[i / 2];
    const float a_i = __uint_as_float((i & 1) ? (pair & 0xffff0000u) : (pair << 16));
    g[i] = kda_gate<kLowerBound>(a_i, dt[i], exp_a_log, p);
  }
  if (__builtin_expect(__builtin_isinf(exp_a_log), 0)) {
    for (int i = 0; i < kGateRows; ++i) {
      const uint32_t pair = a_raw[i / 2];
      const float a_i = __uint_as_float((i & 1) ? (pair & 0xffff0000u) : (pair << 16));
      g[i] = kda_gate_wide<kLowerBound>(a_i, dt[i], a_log, p);
    }
  }
#pragma unroll
  for (int i = 0; i < kGateRows; ++i)
    if (gate_valid) s_decay[gate_t][g0 + i] = __expf(g[i]);
  const float beta = sigmoid(b_raw);
  if (tid < kT) s_beta[tid] = beta;
  uint16_t v_out[kVIters];
#pragma unroll
  for (int it = 0; it < kVIters; ++it) {
    const int idx = tid + it * kBlock;
    const float wi[4] = {wv[it].x, wv[it].y, wv[it].z, wv[it].w};
    v_out[it] = f32_to_bf16(conv_silu(
        bf16_to_f32(v_hist[it][0]),
        bf16_to_f32(v_hist[it][1]),
        bf16_to_f32(v_hist[it][2]),
        bf16_to_f32(v_hist[it][3]),
        wi));
    if (idx < kCols * kT) s_v[idx / kCols][idx % kCols] = bf16_to_f32(v_out[it]);
  }

  // pin the state registers: their loads complete before any store is issued (vmcnt counts stores)
#pragma unroll
  for (int cc = 0; cc < kC; ++cc)
#pragma unroll
    for (int i = 0; i < 16; ++i) asm volatile("" : "+v"(h[cc][i]));
  // ---- global stores: conv windows and ReplaySSM ring rows ----
  uint16_t* iw = p.window + static_cast<int64_t>(widx) * p.stride_iw_line;
  const int64_t ring_head = static_cast<int64_t>(hv) * p.ring_len;
  if (owner) {
    if (conv_valid) {
      if (widx >= 0) {
        uint16_t* wp = iw + conv_t * p.stride_iw_step + cch;
#pragma unroll
        for (int i = 0; i < 3; ++i)
          store_as<uint4>(wp + i * p.stride_iw_win, hist[i + 1]);
      }
      if (is_k && conv_t < p.ring_len) {
        store_as<uint4>(p.rawk + slot * p.stride_rawk_slot + (ring_head + conv_t) * K + c8, pack_bf16x8(y));
      }
    }
    if (gate_valid && gate_t < p.ring_len) {
      float* gp = p.ring_g + slot * p.stride_g_slot + (ring_head + gate_t) * K + g0;
#pragma unroll
      for (int i = 0; i < kGateRows; i += 2)
        store_as<float2>(gp + i, make_float2(g[i], g[i + 1]));
    }
    if (tid < kT && tid < p.ring_len) p.ring_beta[slot * p.stride_beta_slot + ring_head + tid] = beta;
  }
#pragma unroll
  for (int it = 0; it < kVIters; ++it) {
    const int idx = tid + it * kBlock;
    const int t = idx / kCols;
    const int vcol = i_v * kCols + idx % kCols;
    if (idx < kCols * kT) {
      if (widx >= 0) {
        uint16_t* wp = iw + t * p.stride_iw_step + 2LL * H * K + static_cast<int64_t>(hv) * V + vcol;
#pragma unroll
        for (int i = 0; i < 3; ++i)
          wp[i * p.stride_iw_win] = v_hist[it][i + 1];
      }
      if (t < p.ring_len) p.rawv[slot * p.stride_rawv_slot + (ring_head + t) * V + vcol] = v_out[it];
    }
  }
  // LDS visibility only needs lgkmcnt; __syncthreads() would also wait for the ring / window
  // stores above to be acknowledged.
  asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
  __builtin_amdgcn_s_barrier();

  // ---- phase 1b: decayed q / k vectors (threads 0..127, one K row each) ----
  if (tid < K) {
    float D = 1.0f;
#pragma unroll
    for (int t = 0; t < kT; ++t) {
      D *= s_decay[t][tid];
      s_kd[t][tid] = s_k[t][tid] * D;
      s_qd[t][tid] = s_q[t][tid] * D;
    }
  }
  asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
  __builtin_amdgcn_s_barrier();
  // A_ts = sum_i k_t k_s prod_{r=s+1..t} d_r (s < t), B_ts = sum_i q_t k_s prod_{r=s+1..t} d_r (s <= t):
  // thread tid takes row tid % 128 and the entries of half tid / 128; 16-lane partials to s_part.
  {
    const int i = tid & (K - 1);
    const int half = tid >> 7;
    float d[kT], kk[kT], qq[kT];
#pragma unroll
    for (int t = 0; t < kT; ++t) {
      d[t] = s_decay[t][i];
      kk[t] = s_k[t][i];
      qq[t] = s_q[t][i];
    }
    float ab[kNAB];
#pragma unroll
    for (int sx = 0; sx < kT; ++sx) {
      float prod = 1.0f;
#pragma unroll
      for (int t = sx; t < kT; ++t) {
        if (t > sx) {
          prod *= d[t];
          ab[t * (t - 1) / 2 + sx] = kk[t] * kk[sx] * prod;
        }
        ab[kNA + t * (t + 1) / 2 + sx] = qq[t] * kk[sx] * prod;
      }
    }
    constexpr int kH0 = (kNAB + 1) / 2;
    if (half == 0) {
#pragma unroll
      for (int e = 0; e < kH0; ++e) ab[e] = group_sum<16>(ab[e]);
      if ((tid & 15) == 0) {
#pragma unroll
        for (int e = 0; e < kH0; ++e) s_part[i >> 4][e] = ab[e];
      }
    } else {
#pragma unroll
      for (int e = kH0; e < kNAB; ++e) ab[e] = group_sum<16>(ab[e]);
      if ((tid & 15) == 0) {
#pragma unroll
        for (int e = kH0; e < kNAB; ++e) s_part[i >> 4][e] = ab[e];
      }
    }
  }

  // ---- phase 2: a_t = kd_t . h0[:, c], b_t = qd_t . h0[:, c] over this lane's rows, packed fp32 ----
  typedef float f2 __attribute__((ext_vector_type(2)));
  f2 a2[kT][kC], b2[kT][kC];
#pragma unroll
  for (int t = 0; t < kT; ++t)
#pragma unroll
    for (int cc = 0; cc < kC; ++cc) {
      a2[t][cc] = f2{0.0f, 0.0f};
      b2[t][cc] = f2{0.0f, 0.0f};
    }
#pragma unroll
  for (int m = 0; m < 4; ++m) {
#pragma unroll
    for (int t = 0; t < kT; ++t) {
      const float4 kd = load_as<float4>(&s_kd[t][32 * m + 4 * j]);
      const float4 qd = load_as<float4>(&s_qd[t][32 * m + 4 * j]);
      const f2 kd0 = {kd.x, kd.y}, kd1 = {kd.z, kd.w}, qd0 = {qd.x, qd.y}, qd1 = {qd.z, qd.w};
#pragma unroll
      for (int cc = 0; cc < kC; ++cc) {
        const f2 h0 = {h[cc][4 * m], h[cc][4 * m + 1]}, h1 = {h[cc][4 * m + 2], h[cc][4 * m + 3]};
        a2[t][cc] = __builtin_elementwise_fma(h0, kd0, a2[t][cc]);
        a2[t][cc] = __builtin_elementwise_fma(h1, kd1, a2[t][cc]);
        b2[t][cc] = __builtin_elementwise_fma(h0, qd0, b2[t][cc]);
        b2[t][cc] = __builtin_elementwise_fma(h1, qd1, b2[t][cc]);
      }
    }
  }
  float av[kT][kC], bv[kT][kC];
#pragma unroll
  for (int t = 0; t < kT; ++t)
#pragma unroll
    for (int cc = 0; cc < kC; ++cc) {
      av[t][cc] = group_sum<8>(a2[t][cc].x + a2[t][cc].y);
      bv[t][cc] = group_sum<8>(b2[t][cc].x + b2[t][cc].y);
    }
  asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
  __builtin_amdgcn_s_barrier();
  if (tid < kNAB) {
    float acc = s_part[0][tid];
#pragma unroll
    for (int r = 1; r < 8; ++r) acc += s_part[r][tid];
    s_ab[tid] = acc;
  }
  asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
  __builtin_amdgcn_s_barrier();

  // ---- the kT-step solve per column (every lane of the 8-lane group; lane j stores token j) ----
  const int vloc = wave * kBV + cg * kC;
  float ab[kNAB];
#pragma unroll
  for (int e = 0; e < kNAB; ++e) ab[e] = s_ab[e];
  float vn[kT][kC];
#pragma unroll
  for (int t = 0; t < kT; ++t) {
    float vv[kC];
#pragma unroll
    for (int cc = 0; cc < kC; ++cc) vv[cc] = s_v[t][vloc + cc];
    const float bt = s_beta[t];
    float os[kC];
#pragma unroll
    for (int cc = 0; cc < kC; ++cc) {
      float u = av[t][cc];
#pragma unroll
      for (int sx = 0; sx < t; ++sx) u += ab[t * (t - 1) / 2 + sx] * vn[sx][cc];
      vn[t][cc] = (vv[cc] - u) * bt;
      float o = bv[t][cc];
#pragma unroll
      for (int sx = 0; sx <= t; ++sx) o += ab[kNA + t * (t + 1) / 2 + sx] * vn[sx][cc];
      os[cc] = o;
    }
    if (j == t) {
      uint16_t* op = p.o + ((bos + t) * H + hv) * V + col0;
      if constexpr (kC == 4) {
        uint2 pk;
        pk.x = static_cast<uint32_t>(f32_to_bf16(os[0])) | (static_cast<uint32_t>(f32_to_bf16(os[1])) << 16);
        pk.y = static_cast<uint32_t>(f32_to_bf16(os[2])) | (static_cast<uint32_t>(f32_to_bf16(os[3])) << 16);
        store_as<uint2>(op, pk);
      } else if constexpr (kC == 2) {
        store_as<uint32_t>(op, static_cast<uint32_t>(f32_to_bf16(os[0])) | (static_cast<uint32_t>(f32_to_bf16(os[1])) << 16));
      } else {
        *op = f32_to_bf16(os[0]);
      }
    }
  }
}

template <int kC, int kT, bool kLowerBound>
void launch(const HlKdaVerifyParams& params, int64_t heads_total, hipStream_t stream) {
  const dim3 grid(static_cast<uint32_t>((4 / kC) * heads_total));
  hl_kda_verify_kernel<kC, kT, kLowerBound><<<grid, dim3(256), 0, stream>>>(params);
}

template <int kC, int kT>
void launch_gate(bool lower_bound, const HlKdaVerifyParams& params, int64_t heads_total, hipStream_t stream) {
  if (lower_bound) {
    launch<kC, kT, true>(params, heads_total, stream);
  } else {
    launch<kC, kT, false>(params, heads_total, stream);
  }
}

template <int kC>
void launch_steps(int64_t steps, bool lower_bound, const HlKdaVerifyParams& params, int64_t heads_total,
                  hipStream_t stream) {
  switch (steps) {
  case 2: launch_gate<kC, 2>(lower_bound, params, heads_total, stream); break;
  case 3: launch_gate<kC, 3>(lower_bound, params, heads_total, stream); break;
  case 4: launch_gate<kC, 4>(lower_bound, params, heads_total, stream); break;
  case 5: launch_gate<kC, 5>(lower_bound, params, heads_total, stream); break;
  case 6: launch_gate<kC, 6>(lower_bound, params, heads_total, stream); break;
  case 7: launch_gate<kC, 7>(lower_bound, params, heads_total, stream); break;
  case 8: launch_gate<kC, 8>(lower_bound, params, heads_total, stream); break;
  default: TORCH_CHECK(false, "verify tokens must be 2..8, got ", steps);
  }
}

void check_tensor(const at::Tensor& t, at::ScalarType dtype, const at::Tensor& like, const char* name) {
  TORCH_CHECK(t.scalar_type() == dtype, name, " must be ", dtype, ", got ", t.scalar_type());
  TORCH_CHECK(t.device() == like.device(), name, " is on another device");
}

void run(const at::Tensor& mixed_qkv, const at::Tensor& conv_weight, const at::Tensor& conv_state,
         const at::Tensor& cache_indices, at::Tensor& conv_window, const at::Tensor& window_indices,
         const at::Tensor& a, const at::Tensor& b, const at::Tensor& a_log, const at::Tensor& dt_bias,
         const at::Tensor& ssm_state, at::Tensor& ring_v, at::Tensor& ring_k, at::Tensor& ring_g,
         at::Tensor& ring_beta, double scale, std::optional<double> lower_bound,
         std::optional<double> softplus_beta, std::optional<double> softplus_threshold, at::Tensor& output) {
  const int64_t seq_len = mixed_qkv.size(0);
  const int64_t batch = cache_indices.size(0);
  const int64_t steps = conv_window.size(1);
  const int64_t heads = ssm_state.size(1);
  TORCH_CHECK(mixed_qkv.is_cuda(), "tensors must be on the GPU");
  check_tensor(mixed_qkv, at::kBFloat16, mixed_qkv, "mixed_qkv");
  check_tensor(conv_weight, at::kFloat, mixed_qkv, "conv_weight");
  check_tensor(conv_state, at::kBFloat16, mixed_qkv, "conv_state");
  check_tensor(cache_indices, at::kInt, mixed_qkv, "cache_indices");
  check_tensor(conv_window, at::kBFloat16, mixed_qkv, "conv_window");
  check_tensor(window_indices, at::kInt, mixed_qkv, "window_indices");
  check_tensor(a, at::kBFloat16, mixed_qkv, "a");
  check_tensor(b, at::kBFloat16, mixed_qkv, "b");
  check_tensor(a_log, at::kFloat, mixed_qkv, "a_log");
  check_tensor(dt_bias, at::kFloat, mixed_qkv, "dt_bias");
  check_tensor(ssm_state, at::kFloat, mixed_qkv, "ssm_state");
  check_tensor(ring_v, at::kBFloat16, mixed_qkv, "ring_v");
  check_tensor(ring_k, at::kBFloat16, mixed_qkv, "ring_k");
  check_tensor(ring_g, at::kFloat, mixed_qkv, "ring_g");
  check_tensor(ring_beta, at::kFloat, mixed_qkv, "ring_beta");
  check_tensor(output, at::kBFloat16, mixed_qkv, "output");
  TORCH_CHECK(batch * steps == seq_len, "seq_len must be requests x verify tokens");
  TORCH_CHECK(window_indices.size(0) == batch, "a window line per request");
  TORCH_CHECK(mixed_qkv.size(1) == 3 * heads * kKdaK && mixed_qkv.stride(1) == 1, "mixed_qkv must be [seq_len, 3 * H * 128]");
  TORCH_CHECK(conv_state.size(1) == 3 && conv_state.size(2) == mixed_qkv.size(1) && conv_state.stride(2) == 1,
              "conv_state must be [slots, 3, dim]");
  TORCH_CHECK(conv_window.size(2) == 3 && conv_window.size(3) == mixed_qkv.size(1) && conv_window.stride(3) == 1,
              "conv_window must be [lines, steps, 3, dim]");
  TORCH_CHECK(conv_weight.size(0) == mixed_qkv.size(1) && conv_weight.size(1) == 4 && conv_weight.stride(0) == 4 &&
                  conv_weight.stride(1) == 1,
              "conv weight must be a dense [dim, 4]");
  TORCH_CHECK(mixed_qkv.stride(0) % 8 == 0 && conv_state.stride(1) % 8 == 0 && conv_window.stride(2) % 8 == 0 &&
                  a.stride(0) % 8 == 0,
              "channel octets must be 16-byte aligned");
  TORCH_CHECK(a.dim() == 3 && a.size(0) == seq_len && a.size(1) == heads && a.size(2) == kKdaK && a.stride(2) == 1 &&
                  a.stride(1) == kKdaK,
              "a must be [seq_len, H, 128] with contiguous rows");
  TORCH_CHECK(b.dim() == 2 && b.size(0) == seq_len && b.size(1) == heads && b.stride(1) == 1,
              "b must be [seq_len, H] with contiguous rows");
  TORCH_CHECK(a_log.numel() == heads && dt_bias.numel() == heads * kKdaK && a_log.is_contiguous() && dt_bias.is_contiguous(),
              "a_log must be [H], dt_bias [H, 128]");
  TORCH_CHECK(ssm_state.size(2) == kKdaV && ssm_state.size(3) == kKdaK && ssm_state.stride(3) == 1 &&
                  ssm_state.stride(2) == kKdaK && ssm_state.stride(1) == kKdaK * kKdaV,
              "state must be [slots, HV, V, K] with contiguous heads");
  const int64_t ring_len = ring_v.size(2);
  TORCH_CHECK(ring_len >= steps && ring_k.size(2) == ring_len && ring_g.size(2) == ring_len && ring_beta.size(2) == ring_len,
              "rings must hold the verify tokens");
  TORCH_CHECK(ring_v.stride(2) == kKdaV && ring_k.stride(2) == kKdaK && ring_g.stride(2) == kKdaK &&
                  ring_v.stride(1) == ring_len * kKdaV && ring_k.stride(1) == ring_len * kKdaK &&
                  ring_g.stride(1) == ring_len * kKdaK && ring_beta.stride(1) == ring_len && ring_beta.stride(2) == 1,
              "ring rows must be contiguous");
  TORCH_CHECK(output.is_contiguous() && output.numel() == seq_len * heads * kKdaV, "output must be [seq_len, H, 128]");
  TORCH_CHECK(lower_bound.has_value() || (softplus_beta.has_value() && softplus_threshold.has_value()),
              "a lower bound, or the softplus gate's beta and threshold");
  TORCH_CHECK(4 * batch * heads <= INT32_MAX, "too many requests x heads");
  if (batch == 0) {
    return;
  }
  const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(mixed_qkv.device());
  const hipStream_t stream = at::hip::getCurrentHIPStream();
  HlKdaVerifyParams params{};
  params.x = static_cast<const uint16_t*>(mixed_qkv.data_ptr());
  params.conv_w = conv_weight.data_ptr<float>();
  params.conv_state = static_cast<const uint16_t*>(conv_state.data_ptr());
  params.cache_indices = cache_indices.data_ptr<int32_t>();
  params.window = static_cast<uint16_t*>(conv_window.data_ptr());
  params.window_indices = window_indices.data_ptr<int32_t>();
  params.a = static_cast<const uint16_t*>(a.data_ptr());
  params.b = static_cast<const uint16_t*>(b.data_ptr());
  params.A_log = a_log.data_ptr<float>();
  params.dt_bias = dt_bias.data_ptr<float>();
  params.state = ssm_state.data_ptr<float>();
  params.rawv = static_cast<uint16_t*>(ring_v.data_ptr());
  params.rawk = static_cast<uint16_t*>(ring_k.data_ptr());
  params.ring_g = ring_g.data_ptr<float>();
  params.ring_beta = ring_beta.data_ptr<float>();
  params.o = static_cast<uint16_t*>(output.data_ptr());
  params.stride_x_tok = mixed_qkv.stride(0);
  params.stride_cs_line = conv_state.stride(0);
  params.stride_cs_win = conv_state.stride(1);
  params.stride_iw_line = conv_window.stride(0);
  params.stride_iw_step = conv_window.stride(1);
  params.stride_iw_win = conv_window.stride(2);
  params.stride_a_tok = a.stride(0);
  params.stride_b_tok = b.stride(0);
  params.stride_state_slot = ssm_state.stride(0);
  params.stride_rawv_slot = ring_v.stride(0);
  params.stride_rawk_slot = ring_k.stride(0);
  params.stride_g_slot = ring_g.stride(0);
  params.stride_beta_slot = ring_beta.stride(0);
  params.scale = static_cast<float>(scale);
  params.lower_bound = static_cast<float>(lower_bound.value_or(0.0));
  params.softplus_beta = static_cast<float>(softplus_beta.value_or(1.0));
  params.softplus_threshold = static_cast<float>(softplus_threshold.value_or(20.0));
  params.num_heads = static_cast<int32_t>(heads);
  params.ring_len = static_cast<int32_t>(ring_len);
  // value columns per lane: 1 (4 blocks per head) at B <= 5, 2 at B <= 10, else 4 (1 block per head)
  const int64_t heads_total = batch * heads;
  const bool gate = lower_bound.has_value();
  if (batch <= 5) {
    launch_steps<1>(steps, gate, params, heads_total, stream);
  } else if (batch <= 10) {
    launch_steps<2>(steps, gate, params, heads_total, stream);
  } else {
    launch_steps<4>(steps, gate, params, heads_total, stream);
  }
  C10_HIP_CHECK(hipGetLastError());
}

