#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
  m.def("run(Tensor mixed_qkv, Tensor conv_weight, Tensor conv_state, Tensor cache_indices, "
        "Tensor(a!) conv_window, Tensor window_indices, Tensor a, Tensor b, Tensor a_log, Tensor dt_bias, "
        "Tensor ssm_state, Tensor(a!) ring_v, Tensor(a!) ring_k, Tensor(a!) ring_g, Tensor(a!) ring_beta, "
        "float scale, float? lower_bound, float? softplus_beta, float? softplus_threshold, "
        "Tensor(a!) output) -> ()",
        &run);
}
